import csv

def expected_for(rows, total):
    exp = {}
    for row in rows:
        v = int(row["votes"])
        exp[row["candidate"]] = (200 * v + total) // (2 * total)
    return exp

with open("votes.csv") as f:
    names = [r["candidate"] for r in csv.DictReader(f)]

found = []
# Search over all 120-vote partitions? 120 choose 2 is ~7000, times report values 0..100^3 too big.
# Instead: for each partition of 120 into 3 parts, compute expected; check sum==100.
# If sum==100, that partition's expected IS a valid report.
for a in range(1, 119):
    for b in range(1, 120 - a):
        c = 120 - a - b
        if c < 1:
            continue
        exp = expected_for([{"candidate": n, "votes": v} for n, v in zip(names, (a, b, c))], 120)
        if sum(exp.values()) == 100:
            found.append((a, b, c, dict(exp)))
            if len(found) >= 20:
                break
    if len(found) >= 20:
        break

print(len(found))
for f in found:
    print(f)
EOF
